function validateThresholds(thresholds, metricIds) {
  if (!thresholds) {
    return null;
  }

  const validated = {};
  const knownMetrics = new Set(metricIds);

  for (const [metric, min] of Object.entries(thresholds)) {
    if (!knownMetrics.has(metric)) {
      const error = new Error(`Unknown metric id: ${metric}`);
      error.code = 'UNKNOWN_METRIC';
      error.validMetrics = metricIds;
      throw error;
    }
    if (typeof min !== 'number') {
      const error = new Error(`Threshold for ${metric} must be a number, got ${typeof min}`);
      error.code = 'INVALID_THRESHOLD_FORMAT';
      throw error;
    }
    if (min < 0 || min > 1) {
      const error = new Error(`Threshold for ${metric} must be between 0 and 1, got ${min}`);
      error.code = 'INVALID_THRESHOLD_RANGE';
      throw error;
    }
    validated[metric] = min;
  }

  return validated;
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds,
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const metricIds = evaluations.map((m) => m.id);
  const validated = validateThresholds(thresholds, metricIds);

  let thresholdResults = null;
  let passed = true;

  if (validated) {
    thresholdResults = Object.entries(validated).map(([metric, min]) => {
      const evaluation = evaluations.find((e) => e.id === metric);
      const score = evaluation?.score;
      const thresholdPassed = score !== null && score >= min;
      if (!thresholdPassed) {
        passed = false;
      }
      return {
        metric,
        min,
        score: score ?? null,
        passed: thresholdPassed
      };
    });
  }

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholdResults) {
    report.passed = passed;
    report.thresholds = thresholdResults;
  }

  return report;
}

